INSERT INTO coding_problems (id, topic_id, position, difficulty, title, statement, starter_code) VALUES ('0e7cad65-9cd4-5955-8d3b-83120ecb0258', '480e01d7-ca63-5c82-8c09-a7b61243756e', 1, 'EASY', 'Payroll total', 'A payroll file lists the monthly pay of each employee. Print the total.

