INSERT INTO coding_problems (id, topic_id, position, difficulty, title, statement, starter_code) VALUES ('d50d2cf3-e3a8-50b7-9989-fec757d18a64', '480e01d7-ca63-5c82-8c09-a7b61243756e', 3, 'MEDIUM', 'Reverse the words', 'Read one line and print its words in reverse order, separated by exactly one space. A word is a run of characters that are not spaces. The input may start or end with spaces and may have several spaces between words; the output must not.

Input: one line, at most 100000 characters, with at least one word.
Output: the words in reverse order on one line.', 'import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String line = in.nextLine();
        // print the words of line in reverse order
    }
}
');
