INSERT INTO coding_problems (id, topic_id, position, difficulty, title, statement, starter_code) VALUES ('784f6767-9481-5402-9c7b-ca5207baab40', '480e01d7-ca63-5c82-8c09-a7b61243756e', 4, 'HARD', 'Longest unique stretch', 'A log line is a string of letters and digits. Find the length of the longest stretch of consecutive characters in which no character appears twice.

Input: one line with no spaces, between 1 and 100000 characters. Upper and lower case are different characters.
Output: one integer.

Checking every possible stretch is too slow for the largest inputs. Keep a window that moves forward once.', 'import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String s = in.next();
        // print the length of the longest stretch with all different characters
    }
}
');
