INSERT INTO coding_problems (id, topic_id, position, difficulty, title, statement, starter_code) VALUES ('a84fc276-d882-57ac-b170-4a8d2f7e59de', '480e01d7-ca63-5c82-8c09-a7b61243756e', 5, 'HARD', 'Merge meeting slots', 'Meeting slots are given as start and end times. Slots that overlap, or that touch (one ends exactly when the next starts), must be merged into one longer slot.

Input: the first line has n (1 <= n <= 100000). Each of the next n lines has two integers, start and end, with start < end. The slots are in no particular order.
Output: the merged slots sorted by start time, one per line, written as "start end".', 'import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        // read the n slots, merge them, and print the merged slots
    }
}
');
